function rememberUiPanels(){const owner=state?.user.username;if(owner!==expandedUiOwner){expandedUi.clear();touchedUi.clear();expandedUiOwner=owner;return}document.querySelectorAll('[data-ui-section]').forEach(n=>{if(!touchedUi.has(n.dataset.uiSection))return;if(n.open)expandedUi.add(n.dataset.uiSection);else expandedUi.delete(n.dataset.uiSection)})}

function focusPortfolioTarget(){if(view==='portfolio-detail'&&portfolioSection){const target=document.querySelector('[data-portfolio-section="'+portfolioSection+'"]');if(target){target.tabIndex=-1;target.scrollIntoView({block:'start'});target.focus({preventScroll:true});portfolioSection=null}}}

function isUnderflow(amount,number){return number===0&&/[1-9]/.test(String(amount).split(/[eE]/)[0])}
function formatAmount(value){if(!value||value.amount===null||value.amount===undefined)return '—';const number=Number(value.amount);if(!Number.isFinite(number))return '—';if(isUnderflow(value.amount,number))return escape(String(value.amount))+' '+escape(value.currency||'· valuta ikke oplyst');const options=value.currency?{style:'currency',currency:value.currency}:{};if(number!==0&&Math.abs(number)<1){options.maximumSignificantDigits=8;options.minimumSignificantDigits=1}else{options.maximumFractionDigits=value.currency?4:8}return new Intl.NumberFormat('da-DK',options).format(value.amount)+(value.currency?'':' · valuta ikke oplyst')}
function formatQuantity(value){if(value===null||value===undefined)return '—';const number=Number(value);if(!Number.isFinite(number))return '—';if(isUnderflow(value,number))return escape(String(value));return new Intl.NumberFormat('da-DK',number!==0&&Math.abs(number)<0.00000001?{maximumSignificantDigits:10}:{maximumFractionDigits:20}).format(value)}
function formatTime(value){if(!value)return '—';const date=new Date(value);return Number.isNaN(date.getTime())?'Ukendt tidspunkt':new Intl.DateTimeFormat('da-DK',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23',timeZone:'Europe/Copenhagen'}).format(date)+' · dansk tid'}
function pnlMarkup(value,resultLabel='Urealiseret resultat'){if(!value||value.amount===null||value.amount===undefined)return '<span class="pnl neutral">—</span>';const number=Number(value.amount);if(!Number.isFinite(number))return '<span class="pnl neutral">—</span>';const underflow=isUnderflow(value.amount,number);const sign=number>0||(underflow&&!String(value.amount).startsWith('-'))?1:number<0||underflow?-1:0;const label=(sign>0?'Positivt ':sign<0?'Negativt ':'Nul · ')+resultLabel.toLowerCase();return `<span class="pnl ${sign>0?'positive':sign<0?'negative':'neutral'}" aria-label="${label}"><svg class="trend-arrow" viewBox="0 0 20 20" aria-hidden="true"><path d="M4 16 16 4M5 4h11v11" transform="rotate(${sign>0?0:sign<0?90:45} 10 10)" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg><span class="sr-only">${sign>0?'↗':sign<0?'↘':'→'}</span> ${sign>0?'+':''}${formatAmount(value)}</span>`}
function dataIssues(data){const errors=[...data.errors,...(data.order_errors||[])];return errors.length?`<details class="data-issues"><summary>Datastatus · ${errors.length} ${errors.length===1?'punkt kræver':'punkter kræver'} tilpasning</summary>${errors.map(error=>`<p>${escape(error)}</p>`).join('')}</details>`:''}
// Source time determines age. Fetch time never replaces an unknown source time.
function freshness(source,fetched,failed=false,unknownSource=false,now=Date.now()+serverClockOffset,kind='snapshot'){
 const parse=v=>v?Date.parse(v):NaN,sourceAt=parse(source),fetchedAt=parse(fetched);
 const known=Number.isFinite(sourceAt)&&sourceAt<=now,fetchKnown=Number.isFinite(fetchedAt)&&fetchedAt<=now;
 const age=known?Math.max(0,now-sourceAt,fetchKnown?now-fetchedAt:0):fetchKnown?Math.max(0,now-fetchedAt):null;
 const minutes=age===null?null:Math.floor(age/60000),unknown=!known||unknownSource;
 const limits=typeof state!=='undefined'&&state?.dashboard?.policy?.limits||{live_quote:60,snapshot:300,analysis:86400};const limit=limits[kind]||300;const tone=failed||age!==null&&age>limit*1000?'stale':unknown?'unknown':'recent';
 const ageText=minutes===null?'Ukendt alder':minutes<1?'under 1 minut':minutes+' min';const fetchMinutes=fetchKnown?Math.max(0,Math.floor((now-fetchedAt)/60000)):null;const fetchText=fetchMinutes===null?'ukendt':fetchMinutes<1?'under 1 minut':fetchMinutes+' min';
 return {tone,minutes,label:failed?'Seneste opslag fejlede · tidligere data':tone==='stale'?'Forældede data · '+ageText:unknown?'Kildetid ukendt eller delvist ukendt':tone==='warning'?'Hold øje · data er '+ageText+' gamle':'Kildedata er '+ageText+' gamle',detail:(unknown?(known?'Ældste oplyste datatid: '+formatTime(source)+'. ':'')+(fetchKnown?'Hentet for '+fetchText+' siden; det dokumenterer ikke alle dataenes alder.':'Hentetid ukendt.'):'Datatid: '+formatTime(source))+(tone==='stale'?' Opdatér og kontrollér kilden før en beslutning.':'')};
}
function shortAgeLabel(f){return f.label.startsWith('Seneste opslag fejlede')?'Opslag fejlede':f.tone==='unknown'?'Kildetid ukendt':f.tone==='stale'?'Forældet · '+(f.minutes===null?'ukendt alder':f.minutes+' min'):f.minutes===0?'Under 1 min':f.minutes+' min gammel'}
function ageMarkup(source,fetched,failed=false,unknown=false,compact=false){const f=freshness(source,fetched,failed,unknown);return `<div class="data-freshness ${compact?'freshness-compact ':''}freshness-${f.tone}" data-age-source="${escape(source||'')}" data-age-fetched="${escape(fetched||'')}" data-age-failed="${failed?'1':'0'}" data-age-unknown="${unknown?'1':'0'}"><strong class="freshness-label">${escape(compact?shortAgeLabel(f):f.label)}</strong><span class="freshness-detail">${escape(f.detail)}</span></div>`}
function quoteAge(source,fetched,failed=false,sourceName=''){return `<details class="quote-age"><summary>${ageMarkup(source,fetched,failed,false,true)}</summary><div class="quote-age-details"><p>Kildetid: ${formatTime(source)}<br>Hentet: ${formatTime(fetched)}</p>${sourceName?`<p>${escape(sourceName)}</p>`:''}</div></details>`}
function snapshotAge(snapshot,compact=false){const data=snapshot?.data;if(!data)return ageMarkup(null,null,false,false,compact);const times=[data.value?.source_time,...(data.accounts||[]).map(a=>a.source_time),...(data.positions||[]).map(p=>p.price_time)];const valid=times.filter(t=>t&&Number.isFinite(Date.parse(t))&&Date.parse(t)<=Date.now()+serverClockOffset+60000);const oldest=valid.sort((a,b)=>Date.parse(a)-Date.parse(b))[0];return ageMarkup(oldest,data.observed,Boolean(snapshot.last_error),!times.length||valid.length!==times.length,compact)}
function updateFreshness(){const regions=new Map(),rank={recent:0,warning:1,unknown:1,stale:2};document.querySelectorAll('[data-age-source]').forEach(node=>{const f=freshness(node.dataset.ageSource,node.dataset.ageFetched,node.dataset.ageFailed==='1',node.dataset.ageUnknown==='1');const compact=node.classList.contains('freshness-compact');node.className='data-freshness '+(compact?'freshness-compact ':'')+'freshness-'+f.tone;node.querySelector('.freshness-label').textContent=compact?shortAgeLabel(f):f.label;node.querySelector('.freshness-detail').textContent=f.detail;const region=node.closest('[data-pluto-region]');if(region)regions.set(region,Math.max(regions.get(region)||0,rank[f.tone]))});regions.forEach((priority,region)=>{region.classList.toggle('pluto-age-stale',priority===2);region.classList.toggle('pluto-age-warning',priority===1)})}
function plutoDecisionNotice(){const samples=Object.values(state.portfolio_snapshots||{});if(!samples.length)return '';return `<div class="panel"><h3>Kontrollér datagrundlaget før en beslutning</h3><p>Pluto-tal er gemte observationer. Kontrollér kilde og alder i porteføljen; ChatGPT-rapporter opdaterer ikke kontodata.</p><button data-view="portfolios">Se Pluto-data og kildetider →</button></div>`}
function overviewAccounts(){
 const roots=state.portfolios.filter(p=>p.source==='pluto'&&p.active&&p.kind==='portfolio');
 if(!roots.length)return `<section class="panel account-onboarding ${state.report_desk?.main_report?'':'hero'}"><div><small>PLUTO / KONTOOVERBLIK</small><h2>${state.connection.has_tokens?'Hent dine kontotal':'Dine konti samlet ét sted'}</h2><p>${state.connection.has_tokens?'Kontolisten er endnu ikke tilgængelig. Åbn Porteføljer for status.':'Tilslut Pluto for kontotal og beholdninger. Analyser kan læses uafhængigt af forbindelsen.'}</p></div><button data-view="${state.connection.has_tokens?'portfolios':'settings'}">${state.connection.has_tokens?'Åbn porteføljer →':'Tilslut Pluto →'}</button></section>`;
 return `<section class="panel wealth-panel account-overview"><div class="section-heading"><div><small>PLUTO / KONTOOVERBLIK</small><h2>Dine kontotal</h2></div><button data-view="portfolios">Alle porteføljer →</button></div><div class="account-overview-grid">${roots.map(p=>{const snapshot=state.portfolio_snapshots[String(p.id)],d=snapshot?.data,v=d?.value,result=v?.reported_result;return `<article class="account-overview-card" data-pluto-region><h3>${escape(p.name)}</h3><small>Porteføljeværdi inkl. Collections</small><button class="account-number-link account-value ${result?.amount!==null&&result?.amount!==undefined?resultTone(result,v?.value):''}" data-open-portfolio="${p.id}" data-detail-section="value" aria-label="Åbn værdi og datagrundlag for ${escape(p.name)}"><strong class="portfolio-value">${formatAmount(v?.value)}</strong><span aria-hidden="true">→</span></button><details class="quote-age"><summary>${snapshotAge(snapshot,true)}</summary><p>Kildetid for værdi: ${formatTime(v?.source_time)}<br>Hentet: ${formatTime(d?.observed)}</p></details>${result?.amount!==null&&result?.amount!==undefined?`<button class="account-number-link account-result" data-open-portfolio="${p.id}" data-detail-section="value"><small>Plutos oplyste resultat</small>${pnlMarkup(result,'Plutos oplyste resultat')}<small>Afkastperiode ikke oplyst · se grundlaget →</small></button>`:''}${d?.accounts?.length?`<div class="account-cash-links"><small>Kontantbalance</small>${d.accounts.map(a=>`<button class="account-number-link" data-open-portfolio="${p.id}" data-detail-section="cash">${formatAmount(a.balance)} <span aria-hidden="true">→</span></button>`).join('')}</div>`:''}<div class="account-detail-links"><button data-open-portfolio="${p.id}" data-detail-section="holdings">Beholdninger →</button><button data-open-portfolio="${p.id}" data-detail-section="cash">Kontanter →</button><button data-open-portfolio="${p.id}" data-detail-section="orders">Ordrestatus →</button></div></article>`}).join('')}</div><p class="muted account-overview-note">Tryk på et tal for kilde og detaljer. Porteføljer og valutaer vises hver for sig; Collections lægges ikke oveni.</p></section>`
}

function resultTone(){return 'financial-neutral'}
function collectionSpec(portfolio){const snapshot=state.portfolio_snapshots[String(portfolio.id)],d=snapshot?.data;return `<details class="collection-spec"><summary>Collection-specifikation${d?' · '+d.positions.length+' poster':''}</summary>${d?`<p class="muted">${d.positions_complete?'Alle tilgængelige sider hentet':'Indholdet er ikke bekræftet fuldstændigt'}</p><div class="collection-spec-list">${d.positions.map(p=>`<button class="collection-spec-row" data-open-portfolio="${portfolio.id}" data-detail-section="holdings"><span><strong>${escape(p.ticker||p.name)}</strong><small>${formatQuantity(p.quantity)} stk.</small></span><span>${formatAmount(p.value)} ${pnlMarkup(p.unrealized)}</span><span aria-hidden="true">→</span></button>`).join('')||'<p>Ingen indholdsposter leveret. Det betyder ikke automatisk nul beholdninger.</p>'}</div>`:'<p>Indholdet er endnu ikke hentet fra Pluto.</p>'}<button data-open-portfolio="${portfolio.id}" data-detail-section="holdings">Åbn hele specifikationen →</button></details>`}
function collectionBreakdown(portfolio){const children=state.portfolios.filter(p=>p.source==='pluto'&&p.active&&p.kind==='collection'&&p.parent_external_id===portfolio.external_id);return children.length?`<section class="panel collection-breakdown"><h2>Collections i porteføljen</h2><p class="muted">Værdierne indgår allerede i hovedporteføljen.</p>${children.map(p=>`<article><h3>${escape(p.name)}</h3>${portfolioPreview(p)}${collectionSpec(p)}</article>`).join('')}</section>`:''}

function portfolioCard(x){return `<div class="panel portfolio-card ${x.kind==='collection'?'portfolio-card-collection':'portfolio-card-root'}" data-pluto-region><small>${x.source==='pluto'?(x.kind==='collection'?'PLUTO / COLLECTION':'PLUTO / PORTEFØLJE'):'LOKAL PORTEFØLJE'}</small><h2>${escape(x.name)}</h2><span class="badge">${x.active?'● Aktiv':'○ Arkiveret'} · ${x.source==='pluto'?'Pluto':'Lokal enhed'}</span>${x.source==='pluto'&&x.can_trade!==null?`<p class="muted">${x.can_trade?'Pluto bekræfter handelsadgang. Forslag kræver din gennemgang.':'Kun visningsadgang hos Pluto.'}</p>`:''}${x.parent_external_id?`<p class="muted">Tilhører: ${escape(state.portfolios.find(p=>p.source==='pluto'&&p.external_id===x.parent_external_id)?.name||'Portefølje ikke med i listen')}</p>`:''}${portfolioPreview(x)}${x.kind==='collection'?collectionSpec(x):''}<p class="muted">Listeoplysninger opdateret: ${formatTime(new Date(x.updated*1000).toISOString())}</p></div>`}
function portfolioTree(all=state.portfolios){if(!all.length)return empty('Ingen porteføljer hentet','Pluto-listen hentes automatisk, når forbindelsen er klar.');const roots=all.filter(p=>p.source==='pluto'&&p.kind==='portfolio');const grouped=new Set();let html='';for(const root of roots){const children=all.filter(p=>p.source==='pluto'&&p.kind==='collection'&&p.parent_external_id===root.external_id);children.forEach(p=>grouped.add(p.id));html+=`<section class="portfolio-group">${portfolioCard(root)}${children.length?`<div class="collection-children"><p class="muted">Collections nedenfor er allerede inkluderet i porteføljens samlede værdi.</p>${children.map(portfolioCard).join('')}</div>`:''}</section>`}const rest=all.filter(p=>!roots.some(root=>root.id===p.id)&&!grouped.has(p.id));if(rest.length)html+=`<div class="grid">${rest.map(portfolioCard).join('')}</div>`;return html}
function portfolioPreview(portfolio){const snapshot=state.portfolio_snapshots[String(portfolio.id)];return `<div class="portfolio-preview">${snapshot?`${snapshotAge(snapshot)}<small class="portfolio-metric-label">DEPOTVÆRDI</small><button class="account-number-link portfolio-value-link ${resultTone(snapshot.data.value?.reported_result,snapshot.data.value?.value)}" data-open-portfolio="${portfolio.id}" data-detail-section="value"><strong class="portfolio-value">${formatAmount(snapshot.data.value?.value)}</strong><span aria-hidden="true">→</span></button>${snapshot.data.value?.reported_result?.amount!==null&&snapshot.data.value?.reported_result?.amount!==undefined?`<button class="account-number-link" data-open-portfolio="${portfolio.id}" data-detail-section="value">${pnlMarkup(snapshot.data.value.reported_result,'Plutos oplyste resultat')} <small>Plutos resultat · periode ikke oplyst →</small></button>`:''}<p class="muted">Senest registreret værdi. Kildetid: ${formatTime(snapshot.data.value?.source_time)}<br>Indlæst: ${formatTime(snapshot.data.observed)}</p>${snapshot.last_error?`<p class="badge">${escape(snapshot.last_error)}</p>`:''}${snapshot.data.errors?.length?'<p class="badge status-warning">Delvise data — se detaljer</p>':''}`:'<p>Værdier og beholdninger er ikke hentet endnu.</p>'}${portfolio.source==='pluto'?`<button data-open-portfolio="${portfolio.id}">Vis beholdninger og kontanter →</button>`:''}</div>`}
function orderCards(rows,unconfirmed=false){return `<div class="order-cards">${rows.map(row=>`<article class="order-card"><div class="order-card-heading"><strong>${escape(row.name||row.ticker||'Ordre · instrument ikke oplyst')}</strong><span class="badge ${unconfirmed?'status-neutral':'status-warning'}">${escape(row.status)}</span></div><p class="muted">${unconfirmed?'Status kan ikke afgøres ud fra ACCEPTED alene. Posten tælles ikke som afventende.':row.pending_buy?'Afventende køb · endnu ikke en beholdning':'Aktiv ordreobservation fra Pluto'}</p><dl class="order-facts"><div><dt>Ønsket antal</dt><dd>${formatQuantity(row.requested_quantity)}</dd></div><div><dt>Udført antal, oplyst</dt><dd>${formatQuantity(row.filled_quantity)}</dd></div><div><dt>Allokeret beløb</dt><dd>${formatAmount(row.allocated)}</dd></div><div><dt>Ordrebeløb</dt><dd>${formatAmount(row.order_amount)}</dd></div></dl><details><summary>Kilde og reference</summary><p class="muted">${escape(row.sources.join(', '))} · ${row.verified_id?'Ordreference oplyst':'Ingen entydig ordreference oplyst'}</p></details></article>`).join('')}</div>`}
function pendingMarkup(data){const rows=data.pending_orders||[],unconfirmed=data.unconfirmed_orders||[];return `<div class="panel pending-panel" data-pluto-region data-portfolio-section="orders">${ageMarkup(null,data.observed,Boolean(data.snapshot_failed))}<small>ORDRER / ALLOKERET KAPITAL</small><div class="section-heading"><h2>Afventende handler</h2><span class="badge status-warning">${rows.length} observationer</span></div>${rows.length?orderCards(rows):'<p class="muted">Ingen afventende poster identificeret i de hentede svar.</p>'}${unconfirmed.length?`<details class="unconfirmed-orders"><summary>${unconfirmed.length} poster med uafklaret udførelsesstatus</summary><p class="muted">Pluto har returneret ACCEPTED. Det bekræfter hverken en åben eller gennemført handel; posterne vises derfor særskilt.</p>${orderCards(unconfirmed,true)}</details>`:''}<details><summary>Reservationer og datagrundlag</summary><p class="muted">${data.orders_complete?'De tilgængelige ordreopslag er hentet.':'Ordreoversigten er ikke bekræftet fuldstændig. Se datastatus.'}</p><p class="muted">${escape(data.reservation_note||'Reservationsafstemning er ikke udført.')}</p><p class="muted">Poster uden fælles ordre-ID summeres ikke. Ordrebeløb trækkes ikke fra kontantbalancen igen.</p></details></div>`}
function holdingsMarkup(data,portfolio,snapshot){return `<section class="panel holdings-panel financial-panel" data-portfolio-section="holdings"><div class="section-heading"><div><small>PLUTO / BEHOLDNINGER</small><h2>Beholdninger${data.positions_complete?' · alle sider hentet':''}</h2></div><span class="holding-count">${data.positions.length} ${data.positions.length===1?'post':'poster'}</span></div><p class="table-hint">Datomærkerne viser kursens alder. Tryk på et mærke for kildetid og hentetid.</p><div class="scroll financial-scroll"><table class="holdings-table financial-table"><colgroup><col class="col-instrument"><col class="col-quantity"><col class="col-price"><col class="col-value"><col class="col-cost"><col class="col-result"></colgroup><thead><tr><th scope="col">Instrument</th><th scope="col">Antal</th><th scope="col">Senest oplyste pris</th><th scope="col">Værdi</th><th scope="col">Kostpris</th><th scope="col">Urealiseret</th></tr></thead><tbody>${data.positions.map(row=>`<tr data-pluto-region><td><div class="instrument-cell"><span class="instrument-mark" aria-hidden="true">${escape((row.ticker||row.name||'—').slice(0,2).toUpperCase())}</span><div><strong class="instrument-name">${escape(row.name||row.ticker||'Navn ikke oplyst')}</strong><span class="instrument-meta">${escape(row.ticker||'')} · ${row.kind==='collection'?'Collection · indgår i porteføljen':portfolio.kind==='collection'?'Beholdning i Collection':'Direkte beholdning'}</span></div></div></td><td><span class="holding-number">${formatQuantity(row.quantity)}</span></td><td><span class="holding-number">${formatAmount(row.price)}</span>${quoteAge(row.price_time,row.price_observed||data.observed,Boolean(snapshot.last_error),row.price_source||'Pluto · beholdningsopslag')}</td><td><span class="holding-number">${formatAmount(row.value)}</span>${row.value_basis==='calculated_quantity_price'?'<span class="calculation-label">Beregnet · antal × pris</span>':''}</td><td><span class="holding-number">${formatAmount(row.cost_basis)}</span></td><td>${pnlMarkup(row.unrealized,row.unrealized_basis?'Beregnet urealiseret resultat':'Urealiseret resultat')}${row.unrealized_basis?'<span class="calculation-label">Beregnet · værdi − kostpris</span>':''}</td></tr>`).join('')}</tbody></table></div>${data.positions.length?'':'<p>Ingen beholdningsposter hentet. Se eventuelle fejl ovenfor.</p>'}<details class="financial-notes"><summary>Om valuta, beregninger og datakilder</summary><p>Beløb står i instrumentets valuta. En Collection-række må ikke lægges sammen med de samme beholdninger inde i Collection. Grøn ↗ og rød ↘ angiver urealiseret resultat i forhold til kostpris, ikke dagens kursretning. Beregnet værdi bruger antal × senest kendte pris. Beregnet urealiseret resultat fratrækker kostpris i samme valuta; det er ikke Plutos oplyste enkeltpositionsresultat og kan afvige pga. prisens alder, omkostninger, udbytte og valuta. Realiseret resultat vises ikke ud fra disse data.</p></details></section>`}
function cashMarkup(data,snapshot){return `<section class="panel cash-panel financial-panel" data-portfolio-section="cash"><small>PLUTO / KONTANTER</small><h2>Kontanter pr. konto og valuta</h2><div class="scroll financial-scroll"><table class="cash-table financial-table"><colgroup><col><col><col><col><col><col></colgroup><thead><tr><th scope="col">Valuta</th><th scope="col">Kontantbalance</th><th scope="col">Reserveret</th><th scope="col">Hævbart beløb</th><th scope="col">Købekraft</th><th scope="col">Kildetid</th></tr></thead><tbody>${data.accounts.map(a=>`<tr data-pluto-region><td><strong>${escape(a.currency||'Ikke oplyst')}</strong></td><td>${formatAmount(a.balance)}</td><td>${formatAmount(a.reserved)}</td><td>${formatAmount(a.withdrawal_power)}</td><td>${formatAmount(a.buying_power)}</td><td>${quoteAge(a.source_time,data.observed,Boolean(snapshot.last_error))}</td></tr>`).join('')}</tbody></table></div>${data.accounts.length?'':'<p>Ingen kontoposter hentet. Det betyder ikke, at saldoen er nul.</p>'}<details class="financial-notes"><summary>Hvad betyder kontantbeløbene?</summary><p>Hævbart beløb (withdrawalPower) og købekraft er forskellige oplysninger. Ingen af dem behandles automatisk som frit investerbare kontanter. Reserveret viser det oplyste beløb for åbne ordrer. Lokale handelsforslag reserverer ikke penge hos Pluto. Ukendte felter vises som —.</p></details></section>`}
function portfolioDetail(){const portfolio=state.portfolios.find(p=>p.id===selectedPortfolio);if(!portfolio)return empty('Porteføljen findes ikke','Gå tilbage til porteføljelisten.');const snapshot=state.portfolio_snapshots[String(portfolio.id)],data=snapshot?.data;return `<div class="panel detail-heading portfolio-detail-hero"><button data-view="portfolios">← Tilbage til porteføljer</button><h2>${escape(portfolio.name)}</h2><p>${portfolio.kind==='collection'?'Collection · indgår i sin porteføljes samlede værdi':'Portefølje · samlet værdi inklusive Collections'} · Pluto Markets · ${portfolio.active?'Aktiv':'Arkiveret'}</p>${portfolio.active?`<button class="primary" data-fetch-portfolio="${portfolio.id}">Opdatér værdier og beholdninger</button>`:''}<p class="muted">Automatisk opdatering, mens appen er synlig. Kildetiderne ved tallene bevares.</p></div>${data?`<div class="pluto-detail-data" data-pluto-region>${snapshotAge(snapshot)}<section class="panel portfolio-value-panel" data-pluto-region data-portfolio-section="value"><small>PLUTO / KONTOØJEBLIKSBILLEDE</small><h2>Senest registrerede værdi</h2>${quoteAge(data.value?.source_time,data.observed,Boolean(snapshot.last_error))}<button class="account-number-link portfolio-total ${resultTone(data.value?.reported_result,data.value?.value)}" data-portfolio-spec="${portfolio.id}" aria-label="Åbn porteføljens specifikation"><strong class="portfolio-value detail-value">${formatAmount(data.value?.value)}</strong><span aria-hidden="true">→</span></button>${data.value?.reported_result?.amount!==null&&data.value?.reported_result?.amount!==undefined?`<div class="reported-result"><span class="muted">Plutos oplyste resultat</span> ${pnlMarkup(data.value.reported_result,'Plutos oplyste resultat')}<p class="muted">Fra profitLoss på ${portfolio.kind==='collection'?'Collection':'portefølje'}-niveau. Ikke opdelt i realiseret og urealiseret; afkastperiode er ikke oplyst her.</p></div>`:''}<p class="muted">Kildetid: ${formatTime(data.value?.source_time)}<br>Hentet: ${formatTime(data.observed)}</p>${snapshot.last_error?`<p class="trade-warning">${escape(snapshot.last_error)} · Seneste forsøg ${formatTime(snapshot.last_attempt)}</p>`:''}${dataIssues(data)}</section>${portfolio.kind==='portfolio'?collectionBreakdown(portfolio):''}${window.DashboardUI.portfolioHoldings(portfolio.id)}${cashMarkup(data,snapshot)}${pendingMarkup({...data,snapshot_failed:Boolean(snapshot.last_error)})}</div>`:empty('Ingen data hentet','Data hentes automatisk, når Pluto-forbindelsen er klar. Du kan også trykke Opdatér.')}`}

async function loadMcpConsent(){try{const rid=new URLSearchParams(location.search).get('mcp_request');if(!rid)throw Error('Ingen godkendelsesanmodning fundet. Start forbindelsen fra ChatGPT.');const result=await api('mcp/consent?request_id='+encodeURIComponent(rid));$('#mcp-consent-body').innerHTML=`<p>Du er logget ind som <strong>${escape(state.user.username)}</strong>. En ekstern klient anmoder om de følgende funktioner på denne konto.</p><p class="muted">Klient-ID: ${escape(result.client_id)}<br>Returadresse: ${escape(result.redirect_uri)}</p><ul>${result.scope.split(' ').map(scope=>`<li>${escape({'reports:read':'Læse modtagne test- og driftsrapporter','reports:write':'Gemme nye test- og driftsrapporter','hotwatch:read':'Læse motorens signaler, journal og egne depot-/ordreobservationer','hotwatch:manage':'Oprette, pause, genoptage og afslutte egne motorsessioner; serviceprocessen kan læse den særskilt tilsluttede Pluto-konto'}[scope]||scope)}</li>`).join('')}</ul><p>Godkend kun, hvis du selv er ved at oprette forbindelsen. Rapportadgang giver ingen ny motoradgang. HOT WATCH-rettigheder gælder særskilt overvågning og læsning; disse MCP-værktøjer kan ikke udføre eller ændre handler.</p><div class="actions"><button class="primary" data-mcp-consent="approve">Godkend de viste rettigheder</button><button data-mcp-consent="deny">Afvis</button></div>`}catch(error){const box=$('#mcp-consent-body');if(box)box.textContent=error.message}}
function reportInbox(){return window.ReportUI.shell()}
function showIngestedReport(report){window.ReportUI.show(report)}
function newsPanel(){const feed=state.automation.news||[],status=state.automation.news_refresh;return `<div class="panel news-panel"><small>MARKED / OFFICIELLE KILDER</small><div class="actions"><h2>Seneste nyt fra ECB</h2><button id="refresh-news" class="primary">Opdatér nyheder ↻</button></div><p class="muted">Officielle pressemeddelelser fra Den Europæiske Centralbank. Hentes ved klik — ingen cron eller AI-analyse.</p>${status?.succeeded?`<p class="muted">Senest opdateret: ${formatTime(new Date(status.succeeded*1000).toISOString())}</p>`:''}${status?.error?`<p class="badge status-warning">${escape(status.error)}</p>`:''}<div class="news-grid">${feed.length?feed.map(n=>`<article class="news-card"><span class="badge status-neutral">ECB · Officiel meddelelse</span><h3>${escape(n.title)}</h3><p class="muted">${formatTime(n.published)}</p>${n.summary?`<p>${escape(n.summary.slice(0,600))}${n.summary.length>600?'…':''}</p>`:''}<a href="${escape(n.url)}" target="_blank" rel="noopener noreferrer">Læs hos ECB ↗</a></article>`).join(''):empty('Ingen nyheder hentet endnu','Tryk Opdatér nyheder for at hente det officielle feed.')}</div><p class="muted">Kilden dækker centralbank og økonomi; den dækker ikke alle aktiemarkeder. Meddelelserne vises på kildens sprog og er ikke handelssignaler.</p></div>`}
