// Read-only refresh is automatic while visible, or explicitly requested by the user.
function refreshCurrent(options={}){
 const wantsAll=options.all||options.automatic;
 if(currentRefreshPromise){if(!wantsAll||currentRefreshAll)return currentRefreshPromise;return currentRefreshPromise.then(()=>refreshCurrent(options))}
 currentRefreshAll=Boolean(wantsAll||['overview','portfolios'].includes(view));
 currentRefreshPromise=performRefresh(options).finally(()=>{currentRefreshPromise=null;currentRefreshAll=false});
 return currentRefreshPromise;
}
async function performRefresh({automatic=false,all=false}={}){
 if(userRefreshBusy||!state)return;
 if(document.querySelector('dialog[open]')||document.activeElement?.matches('input,textarea,select')){notice('Afslut feltet eller luk dialogen før opdatering.');return}
 const epoch=sessionEpoch,target=view,pid=selectedPortfolio,status=$('#refresh-status'),button=$('#refresh-current');userRefreshBusy=true;button.disabled=true;status.dataset.kind='loading';status.textContent='Opdaterer…';let failures=0,done=0,plutoMessage='',plutoAttempted=false,paused=false;const issueDetails=[];
 try{
  if((all||automatic||['overview','portfolios','portfolio-detail'].includes(target))&&state.connection.has_tokens){
   plutoAttempted=true;
   // Refresh existing account data, including the list, without opening new consent.
   if(all||automatic||target!=='portfolio-detail'){try{await api('portfolios/sync',{automatic})}catch(error){if(error.status===409||error.status===401)throw error;failures++;issueDetails.push('Kontoliste: '+error.message)}}
   const latest=await api('state');if(epoch!==sessionEpoch||!state)return;
   const items=latest.portfolios.filter(p=>p.source==='pluto'&&p.active&&(all||automatic||target!=='portfolio-detail'||p.id===pid));
   for(const p of items){if(epoch!==sessionEpoch||!state)break;if(automatic&&document.hidden){paused=true;break}status.textContent=(automatic?'Opdaterer automatisk · ':'Henter Pluto · ')+p.name+'…';try{const r=await api('portfolios/data',{id:p.id,automatic});if(!r.cached)done++;if(r.complete===false){failures++;issueDetails.push(p.name+': '+(r.errors?.length?r.errors.join(' · '):'Ordre- eller beholdningsoversigten er ikke bekræftet fuldstændig'))}}catch(error){if(error.status===409||error.status===401)throw error;failures++;issueDetails.push(p.name+': '+error.message)}}
  }
  if(epoch!==sessionEpoch||!state)return;
  await refresh({background:automatic});
  if(epoch!==sessionEpoch||!state)return;
  if(!automatic&&['inbox','reports','report-archive'].includes(view))await window.ReportUI.load();
  if(!automatic)await window.MarketUI.refreshVisible();
  if(epoch!==sessionEpoch||!state)return;
  if(state.report_desk?.unavailable){failures++;issueDetails.push('Analyserapporter kunne ikke indlæses')}
  if(automatic)for(const p of state.portfolios.filter(p=>p.source==='pluto'&&p.active)){const snapshot=state.portfolio_snapshots[String(p.id)],issues=[snapshot?.last_error,...(snapshot?.data?.errors||[]),...(snapshot?.data?.order_errors||[])].filter(Boolean);if(issues.length&&!issueDetails.some(x=>x.startsWith(p.name+': '))){failures++;issueDetails.push(p.name+': '+issues.join(' · '))}}
  plutoMessage=[...new Set(issueDetails)].slice(0,3).join(' · ');
  status.dataset.kind=failures?'warning':paused?'info':'success';status.textContent=paused?'Automatisk opdatering er sat på pause, mens appen er skjult.':failures?'Opdatering med fejl eller delvise data — kontrollér datamærker og Pluto-forbindelsen. '+plutoMessage:done?(automatic?'Pluto opdateret automatisk kl. ':'Pluto hentet kl. ')+new Date().toLocaleTimeString('da-DK',{timeZone:'Europe/Copenhagen'})+' · kildetider vises ved tallene.':automatic?'Gemte Pluto-data genindlæst. Automatisk læsning højst hvert femte minut; se kildetider ved tallene.':'Visning og rapporter genindlæst. Pluto-kontodata er ikke hentet.';
 }catch(error){if(epoch!==sessionEpoch||!state)return;status.dataset.kind='error';status.textContent='Opdatering mislykkedes — tidligere data kan være forældede. '+error.message;try{await refresh({background:automatic})}catch{}}
 finally{if(plutoAttempted&&epoch===sessionEpoch)nextAutomaticAt=paused?0:Date.now()+300000;userRefreshBusy=false;button.disabled=false}
}
// Successful refreshes are transient; warnings stay available until the next refresh.
let refreshStatusTimer=null;
const refreshStatus=$('#refresh-status');
new MutationObserver(()=>{
 clearTimeout(refreshStatusTimer);
 if(!state||!refreshStatus.textContent.trim()){refreshStatus.hidden=true;return}
 refreshStatus.hidden=false;
 if(['success','info'].includes(refreshStatus.dataset.kind)){
  const epoch=sessionEpoch;
  refreshStatusTimer=setTimeout(()=>{if(epoch===sessionEpoch&&['success','info'].includes(refreshStatus.dataset.kind))refreshStatus.hidden=true},3000);
 }
}).observe(refreshStatus,{childList:true,characterData:true,subtree:true,attributes:true,attributeFilter:['data-kind']});
let pullStart=null,pullDistance=0,pullClaimed=false,pullHideTimer=null;
const pullHint=$('#pull-refresh-status');
function pullMessage(text){clearTimeout(pullHideTimer);pullHint.textContent=text;pullHint.hidden=!text;document.body.classList.toggle('pull-refresh-visible',Boolean(text))}
function resetPull(){pullStart=null;pullDistance=0;pullClaimed=false}
function atPageTop(){return Math.max(window.scrollY,document.documentElement.scrollTop,document.body.scrollTop)<=2}
function canPull(target){return Boolean(state&&atPageTop()&&!document.querySelector('dialog[open],#content form[data-dirty="true"]')&&!target.closest('input,textarea,select,[contenteditable]')&&!document.activeElement?.matches('input,textarea,select'))}
async function finishPull(){
 const epoch=sessionEpoch;resetPull();pullMessage(currentRefreshPromise?'Opdatering er i gang — henter resultatet…':'Opdaterer Pluto-data og rapporter…');
 const status=$('#refresh-status'),observer=new MutationObserver(()=>{if(epoch===sessionEpoch)pullMessage(status.textContent)});observer.observe(status,{childList:true,subtree:true});
 try{await refreshCurrent({all:true});if(epoch===sessionEpoch)pullMessage(status.textContent||'Visningen er genindlæst.')}catch{pullMessage('Opdatering mislykkedes. Prøv knappen Opdatér.')}
 finally{observer.disconnect();if(epoch!==sessionEpoch)pullMessage('');else pullHideTimer=setTimeout(()=>pullMessage(''),2000)}
}
document.addEventListener('touchstart',event=>{resetPull();if(event.touches.length===1&&canPull(event.target))pullStart={x:event.touches[0].clientX,y:event.touches[0].clientY}},{passive:false,capture:true});
document.addEventListener('touchmove',event=>{
 if(!pullStart)return;
 if(event.touches.length!==1){resetPull();pullMessage('');return}
 const dx=event.touches[0].clientX-pullStart.x,dy=event.touches[0].clientY-pullStart.y;
 if(dy< -6||Math.abs(dx)>Math.max(18,Math.abs(dy)*1.3)||!atPageTop()){resetPull();pullMessage('');return}
 // Claim the first downward move before native scrolling takes ownership.
 if(dy>=4&&dy>=Math.abs(dx)&&event.cancelable){event.preventDefault();pullClaimed=true}
 if(!pullClaimed)return;
 pullDistance=Math.max(0,dy);
 if(dy>=8)pullMessage(dy>=72?'Slip for at opdatere alle data':'Træk ned for at opdatere…');
},{passive:false,capture:true});
document.addEventListener('touchend',()=>{if(!pullStart)return;const triggered=pullClaimed&&pullDistance>=72;resetPull();if(triggered)finishPull();else pullMessage('')},{passive:true});
document.addEventListener('touchcancel',()=>{resetPull();pullMessage('')},{passive:true});
setInterval(updateFreshness,30000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden){updateFreshness();maybeAutoRefresh()}});
let deskPollBusy=false;setInterval(async()=>{if(deskPollBusy||userRefreshBusy||editingData()||!state||document.hidden||document.querySelector('dialog[open]')||document.activeElement?.matches('input,select,textarea')||!['overview','radar','portfolios','trade','journal','inbox','reports'].includes(view)||document.querySelector('#report-mode')?.value==='true')return;deskPollBusy=true;try{const desk=await api('reports/desk');if(JSON.stringify(desk)!==JSON.stringify(state.report_desk)){state.report_desk=desk;render()}}catch{}finally{deskPollBusy=false}},90000);

// Pause background rendering while a user edits a form or chooses report history.
function editingData(){return Boolean(document.querySelector('dialog[open],#content form[data-dirty="true"]')||document.activeElement?.matches('input,textarea,select')||['report-archive','mcp-consent'].includes(view)||document.querySelector('#report-mode')?.value==='true')}
async function maybeAutoRefresh({force=false}={}){
 if(!state||document.hidden||userRefreshBusy||editingData())return;
 if(pendingAutoRender){render();return}
 if(!force&&Date.now()<nextAutomaticAt||!(state.connection.connected||state.connection.can_renew))return;
 await refreshCurrent(force?{all:true}:{automatic:true});
}
document.addEventListener('input',e=>{window.TradeUI.change(e);const form=e.target.closest('#content form');if(form)form.dataset.dirty='true'});
document.addEventListener('focusout',()=>{if(pendingAutoRender)setTimeout(()=>{if(state&&!editingData())render()},0)});
setInterval(maybeAutoRefresh,30000);

// Refresh stored values without initiating extra Pluto or EODHD requests.
let storedPollBusy=false;
setInterval(async()=>{
 if(storedPollBusy||userRefreshBusy||!state||document.hidden||editingData()||view==='hot-watch'||document.querySelector('dialog[open]'))return;
 const epoch=sessionEpoch,currentView=view;storedPollBusy=true;
 try{
  const current=await api('state');
  if(epoch!==sessionEpoch||!state||view!==currentView||document.hidden)return;
  const previous={...state};delete previous.automation;delete previous.report_desk;delete previous.time;
  const next={...current};delete next.time;
  serverClockOffset=Date.parse(current.time)-Date.now();
  if(JSON.stringify(previous)!==JSON.stringify(next)){state={...state,...current};if(editingData())pendingAutoRender=true;else render()}
 }catch{}finally{storedPollBusy=false}
},30000);

// Explanations are attached to the existing signal controls, including controls
// rendered later by the radar and HOT WATCH views.
function attachSignalHelp(root=document){
 const selector='button[data-trade-watch],button[data-trade-candidate],button[data-trade-test-buy]';
 const buttons=[];if(root.matches?.(selector))buttons.push(root);if(root.querySelectorAll)buttons.push(...root.querySelectorAll(selector));
 for(const b of buttons){
  if(b.dataset.signalHelpAttached==='true')continue;
  b.dataset.signalHelpAttached='true';const help=document.createElement('button');help.type='button';help.className='signal-help';help.textContent='?';help.setAttribute('aria-label','Hvorfor dette signal?');
  if(b.dataset.tradeWatch)help.dataset.explainWatch=b.dataset.tradeWatch;
  else if(b.dataset.tradeCandidate){help.dataset.explainReport=b.dataset.tradeReport;help.dataset.explainCandidate=b.dataset.tradeCandidate}
  else help.dataset.explainTest='true';
  b.insertAdjacentElement('afterend',help);
 }
}
const signalReasons={ENTRY_RULES:'Strategiens betingelser for køb er opfyldt. De ser på kursens retning, styrke, handelsaktivitet og eventuelle kursbrud.',EXIT_RULES:'Strategiens betingelser for salg er opfyldt.',TRAILING_EXIT:'Kursen er faldet til strategiens grænse i forhold til den seneste top.',STOP_BREACHED:'Den fastsatte stopgrænse er overskredet.',EXIT_DEADLINE:'Den fastsatte frist for at forlade positionen er nået.',HYSTERESIS_HOLD:'Købssignalet holdes kortvarigt, mens den målte styrke fortsat opfylder strategiens fastholdelsesregel.',WARMUP:'Der er endnu ikke nok sammenlignelige observationer til beregningen.',DATA_STALE:'Kursdata er for gamle til et aktuelt signal.',DATA_UNVERIFIED:'Kurskilden er endnu ikke verificeret.',NO_TRIGGER:'Ingen af strategiens betingelser har udløst et signal.',CONFIRMATION_PENDING:'Signalerne mangler endnu de krævede bekræftelser.',SPREAD_TOO_WIDE:'Forskellen mellem købs- og salgskurs er større end den tilladte grænse.',POSITION_CONTEXT_UNKNOWN:'Den aktuelle depotposition kunne ikke bekræftes.'};
async function explainSignal(b){
 const user=state?.user?.username;let title='Hvorfor dette signal?',body='';
 if(b.hasAttribute('data-explain-test')){title='PEPE · testsignal';body='<p>Dette signal er oprettet til at afprøve handelsforløbet. Det bygger ikke på en markedsberegning og er ikke en købs- eller salgsvurdering.</p>'}
 else if(b.dataset.explainWatch){
  const result=await api('v1/hotwatch/sessions/'+encodeURIComponent(b.dataset.explainWatch)+'?is_test=false');if(state?.user?.username!==user||!b.isConnected)return;
  const s=result.session||{},c=s.latest_calculation||{},codes=Array.isArray(c.reason_codes)?c.reason_codes:[],display=Array.isArray(s.display_reason_codes)?s.display_reason_codes:[],changed=s.signal!==c.signal;
  title=(s.request?.ticker||'Instrument')+' · signalets begrundelse';
  const descriptions=codes.map(code=>signalReasons[code]||'Der findes endnu ingen dansk forklaring på årsagen: '+code+'.');
  const metrics=c.supporting_metrics||{},fmt=v=>new Intl.NumberFormat('da-DK',Number(v)!==0&&Math.abs(Number(v))<0.01?{maximumSignificantDigits:3}:{maximumFractionDigits:2}).format(Number(v));
  const values=[['Kursændring over de seneste tre observationsintervaller',metrics.return_3_pct,'%'],['Afstand til seneste top',metrics.distance_high_pct,'%']].filter(([,v])=>v!==null&&v!==undefined&&v!==''&&Number.isFinite(Number(v)));
  const available=v=>v!==null&&v!==undefined&&v!==''&&Number.isFinite(Number(v));
  const q=s.data_status||{},price=v=>new Intl.NumberFormat('da-DK',{maximumSignificantDigits:10}).format(Number(v)),currency=q.currency||s.latest_currency||s.request?.quote_currency||'',quote=v=>available(v)?escape(price(v))+(currency?' '+escape(currency):' · valuta ukendt'):'Ikke oplyst';
  const at=v=>v?escape(formatTime(v)):'tidspunkt mangler';
  const quoteState=({FRESH:'aktuelle ved opslaget',STALE:'for gamle',UNAVAILABLE:'ikke tilgængelige'})[q.quote_status]||'status ukendt';
  const marketFacts=`<section class="signal-market-facts"><h3>Handelsaktivitet og priser</h3><p>Volumen i beregningsintervallet: <strong>${available(metrics.interval_volume)?escape(fmt(metrics.interval_volume)):'Ikke oplyst'}</strong>${available(metrics.relative_volume)?' · '+escape(fmt(metrics.relative_volume))+' gange gennemsnittet af de sammenlignede intervaller':''}</p><p>Spread ved beregningen: <strong>${available(metrics.spread_pct)?escape(fmt(metrics.spread_pct))+' %':'Ikke oplyst'}</strong> <small>· forskellen mellem købs- og salgskurs</small></p><p>Bedste købsbud (bid): <strong>${quote(q.bid)}</strong>${available(q.bid)?' · '+at(q.bid_at):''}<br>Bedste salgspris (ask): <strong>${quote(q.ask)}</strong>${available(q.ask)?' · '+at(q.ask_at):''}</p><p class="muted">Bud og udbud er den seneste separate observation (${escape(quoteState)}) og kan være fra et andet tidspunkt end signalberegningen.</p></section>`;
  body=`<p><strong>Aktuel status: ${escape(s.display_status||'Ikke oplyst')}</strong></p>${changed?'<p>Den seneste beregning er ikke det aktuelle signal. Status kan være ændret af datakvalitet eller andre kontroller.</p>':''}<p>${escape(descriptions.join(' ')||'Der er endnu ikke gemt en begrundelse for beregningen.')}</p>${display.length?`<p>Aktuelle forhold: ${escape(display.map(code=>signalReasons[code]||'Se detaljer om '+code).join(' · '))}</p>`:''}${values.length?`<ul>${values.map(([label,value,unit])=>`<li>${escape(label)}: ${escape(fmt(value))}${escape(unit)}</li>`).join('')}</ul>`:''}${marketFacts}<p class="muted">Beregnet: ${escape(c.calculation_timestamp?formatTime(c.calculation_timestamp):'ikke oplyst')} · Kursdata: ${escape(c.data_timestamp?formatTime(c.data_timestamp):'ikke oplyst')}</p><p class="muted">Tallene beskriver den seneste gemte beregning; de er ikke en garanti for fremtidig udvikling.</p>`;
 }else{
  const record=[...(state?.report_desk?.candidates||[]),...(state?.report_desk?.dormant_candidates||[])].find(r=>r.report_id===b.dataset.explainReport&&r.candidate?.candidate_id===b.dataset.explainCandidate);
  const decision=record?.decision||record?.candidate?.decision,candidate=record?.candidate||{};title=(candidate.ticker||'Instrument')+' · rapportens vurdering';
  const why=decision?.reason||candidate.assessment;body=`<p><strong>Kilde: rapportens vurdering</strong></p><p>${escape(why||'Rapporten indeholder ingen begrundelse, der kan vises her.')}</p>${decision?.next_trigger?`<p><strong>Det næste, der holdes øje med:</strong> ${escape(decision.next_trigger)}</p>`:''}<p class="muted">Vurderet: ${escape(decision?.decided_at?formatTime(decision.decided_at):record?.generated_at?formatTime(record.generated_at):'ikke oplyst')}. Rapportens vurdering er ikke det samme som et beregnet HOT WATCH-signal.</p>`;
 }
 let dialog=document.getElementById('signal-explanation-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='signal-explanation-dialog';dialog.className='quick-trade-dialog signal-explanation-dialog';document.body.append(dialog)}
 dialog.innerHTML=`<div class="overview-detail-header"><h2>${escape(title)}</h2><button type="button" data-explanation-close aria-label="Luk forklaring">✕</button></div>${body}`;dialog.showModal();dialog.querySelector('[data-explanation-close]')?.focus();
}
document.addEventListener('click',async e=>{const close=e.target.closest('[data-explanation-close]');if(close){close.closest('dialog')?.close();return}const b=e.target.closest('[data-explain-watch],[data-explain-candidate],[data-explain-test]');if(!b)return;try{await explainSignal(b)}catch(error){notice('Forklaringen kunne ikke hentes: '+error.message,'error')}});
new MutationObserver(records=>{for(const r of records)for(const n of r.addedNodes)if(n.nodeType===1)attachSignalHelp(n)}).observe(document.body,{childList:true,subtree:true});
attachSignalHelp();

function showProfile(){$('#profile-username').textContent=state.user.username;const dialog=$('#profile-dialog'),form=$('#profile-form'),profile=state.profile||{};for(const key of ['name','email','street','postal_code','city','birth_date'])form.elements[key].value=profile[key]||'';for(const key of ['contact_consent','marketing_consent'])form.elements[key].value=profile[key]===true?'yes':profile[key]===false?'no':'';$('#profile-close').hidden=!profile.complete;$('#profile-error').textContent='';if(!dialog.open)dialog.showModal()}
$('#profile-dialog').addEventListener('cancel',e=>{if(!state?.profile?.complete)e.preventDefault()});

async function loadAdminUsers(){try{const result=await api('admin/users');const box=$('#admin-users');if(view!=='admin'||!box)return;box.innerHTML=result.users.map(u=>{const p=u.profile||{},val=v=>escape(v||'Ikke oplyst'),choice=v=>v===true?'Ja':v===false?'Nej':'Ikke valgt';return `<details class="admin-user"><summary><strong>${val(u.username)}</strong><span>${u.role==='admin'?'Administrator':'Bruger'} · ${u.active?'Aktiv':'Deaktiveret'}</span></summary><div class="admin-profile"><p><strong>Navn:</strong> ${val(p.name)}</p><p><strong>Mail:</strong> ${val(p.email)}</p><p><strong>Adresse:</strong> ${val([p.street,[p.postal_code,p.city].filter(Boolean).join(' ')].filter(Boolean).join(', ')||p.address)}</p><p><strong>Fødselsdato:</strong> ${val(displayDate(p.birth_date))}</p><p><strong>Kontakt:</strong> ${choice(p.contact_consent)} · <strong>Markedsføring:</strong> ${choice(p.marketing_consent)}</p></div>${u.role==='member'&&u.active?`<details class="admin-password"><summary>Giv brugeren en ny adgangskode</summary><p>Brugerens eksisterende sessioner logges ud. Del den nye kode sikkert med brugeren.</p><form class="admin-password-form" data-user-id="${Number(u.id)}"><label>Ny adgangskode<input type="password" name="new_password" autocomplete="new-password" minlength="14" maxlength="1024" required></label><label>Gentag ny adgangskode<input type="password" name="repeat_password" autocomplete="new-password" minlength="14" maxlength="1024" required></label><label>Din administratoradgangskode<input type="password" name="admin_password" autocomplete="current-password" maxlength="1024" required></label><button class="primary" type="submit">Gem ny adgangskode</button><p role="status" aria-live="polite"></p></form></details>`:''}</details>`}).join('')}catch(error){const box=$('#admin-users');if(box)box.textContent=error.message}}
let postcodeLookup=0;
document.querySelector('#profile-form [name=postal_code]').addEventListener('input',async e=>{const code=e.target.value,form=e.target.form,serial=++postcodeLookup,status=$('#postcode-status');status.textContent='';if(!/^[0-9]{4}$/.test(code))return;form.elements.city.value='';const oldCity=form.elements.city.value;status.textContent='Slår postnummer op…';try{const r=await api('profile/postcode?code='+encodeURIComponent(code));if(serial!==postcodeLookup||form.elements.postal_code.value!==code||form.elements.city.value!==oldCity)return;form.elements.city.value=r.city;status.textContent='By udfyldt fra lokal postnummerliste · GeoNames.'}catch(error){if(serial===postcodeLookup)status.textContent='Byen kan udfyldes manuelt.'}});
